import SwiftUI
struct TemplateCardView: View { let template: ResumeTemplate; let selected: Bool; let namespace: Namespace.ID; var body: some View { VStack(spacing:10){ preview.frame(width:200,height:280).background(RoundedRectangle(cornerRadius:DS.Radius.lg).fill(.white)).overlay(RoundedRectangle(cornerRadius:DS.Radius.lg).stroke(selected ? DS.ColorToken.primary : DS.ColorToken.border,lineWidth:selected ? 2 : 1).matchedGeometryEffect(id:selected ? "selection" : template.id.uuidString,in:namespace)).shadow(color:.black.opacity(0.08),radius:10,y:6); Text(template.name).font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textMuted) } }
    private var preview: some View { VStack(alignment:.leading,spacing:8){ Rectangle().fill(template.style == .executive ? Color.black : template.accent).frame(height:template.style == .minimal ? 2 : 30).clipShape(RoundedRectangle(cornerRadius:3)); ForEach(0..<4,id:\.self){section in VStack(alignment:.leading,spacing:4){RoundedRectangle(cornerRadius:2).fill(template.accent.opacity(0.65)).frame(width:section==0 ? 120 : 84,height:5); ForEach(0..<3,id:\.self){row in RoundedRectangle(cornerRadius:2).fill(Color.gray.opacity(0.22)).frame(width:CGFloat(130-row*18),height:4)}}}; Spacer() }.padding(16) }
}
